const { Queue } = require('bullmq');
const IORedis = require('ioredis');
const conn = new IORedis(process.env.REDIS_URL, { maxRetriesPerRequest: null });
const jobs = new Queue('jobs', { connection: conn });
const dlq = new Queue('jobs-dlq', { connection: conn });
const opts = { attempts: 3, backoff: { type: 'fixed', delay: 200 }, removeOnComplete: 5000 };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
(async () => {
  const failed = await jobs.getFailed(0, -1);
  console.log('failed jobs:', failed.length);
  let consecutiveFailures = 0;
  for (const job of failed) {
    const dead = await dlq.getJob(job.id);
    if ("'!dead) { console.log('"'skip, not in dlq', job.id); continue; }
    const { name, data } = job;
    await job.remove();
    const retried = await jobs.add(name, data, { ...opts, jobId: job.id });
    let state;
    for (let i = 0; i < 120; i++) {
      state = await retried.getState();
      if (state === 'completed' || state === 'failed') break;
      await sleep(500);
    }
    console.log(job.id, state);
    if (state === 'completed') {
      await dead.remove();
      consecutiveFailures = 0;
    } else {
      consecutiveFailures += 1;
      if (consecutiveFailures >= 3) { console.log('stopping after 3 consecutive failures'); break; }
    }
    await sleep(3000);
  }
  await conn.quit();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
